import figma from "figma";

const instance = figma.selectedInstance;

const attr = (name, value) => {
  if (value === undefined || value === false) return "";
  if (value === true) return ` ${name}`;
  if (typeof value === "number") return ` ${name}={${value}}`;
  return value.startsWith("{") ? ` ${name}=${value}` : ` ${name}="${value}"`;
};
const codeOf = (node) =>
  node && node.type === "INSTANCE" ? node.executeTemplate().example : undefined;

const icon = codeOf(instance.getInstanceSwap("Icon"));
const size = instance.getEnum("Size", { sm: "sm", md: "md", lg: "lg" });
const disabled = instance.getEnum("State", {
  Default: undefined,
  Hover: undefined,
  Pressed: undefined,
  Disabled: true,
});

export default {
  id: "Icon button",
  example: figma.code`<HvIconButton${attr("size", size)}${attr("disabled", disabled)}>${icon ?? ""}</HvIconButton>`,
  imports: ['import { HvIconButton } from "@pentaho/uikit-react-core";'],
  metadata: { nestable: true },
};
